'use strict';
(() => {
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const A='assets/', KEY='wetland-explorers-demo-v2';
const topics=window.WETLAND_TOPICS, baseQuestions=window.WETLAND_QUESTIONS;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function finishedModuleOne(existing={}){const result={};for(const t of topics.filter(t=>t.id==='invertebrates'))for(const mode of ['in-class','after-class']){const key=t.id+':'+mode;if(existing[key]?.review){result[key]=existing[key];continue;}const qs=baseQuestions.filter(q=>q.topic===t.id&&q.mode===mode);result[key]={key,topic:t.id,mode,at:'2026-11-10T04:00:00.000Z',questions:JSON.parse(JSON.stringify(qs)),answers:Object.fromEntries(qs.map(q=>[q.id,q.type==='mc'?q.correct:'Sample demo response: organism adaptations, habitat conditions and food-web relationships help explain ecological consequences. Conservation decisions should consider evidence and uncertainty.'])),review:{score:8,feedback:'Sample demo review: completed activity with an explanation of ecological connections.',at:'2026-11-10T05:00:00.000Z'},demoSample:true};}return result;}
function initialDemoSubmissions(existing={}){const keep=Object.fromEntries(Object.entries(existing).filter(([key,v])=>!v.demoSample||v.topic==='invertebrates'));return {...keep,...finishedModuleOne(keep)};}
const fresh=()=>({version:2,modulePreset:4,moduleCodes:{},unlockedModules:{invertebrates:true,vertebrates:true},course:'biodiversity',coins:240,pet:'spoonbill',equipped:'hat',inventory:{hat:1,crown:0,food:3,recovery:2},stats:{crab:{health:92,hunger:68,stamina:84},spoonbill:{health:90,hunger:76,stamina:88}},submissions:finishedModuleOne(),rewards:[],activityDays:[],loginClaim:null,restDays:{},customQuestions:[],assets:[],scene:null,settings:{display:'standard',motion:true}});
let state=fresh(),storageEnabled=true,role='student',loggedOut=false;
try {const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored?.version===2)state={...fresh(),...stored,...(stored.modulePreset===4?{}:{modulePreset:4,unlockedModules:{invertebrates:true,vertebrates:true},submissions:initialDemoSubmissions(stored.submissions)})};localStorage.setItem(KEY,JSON.stringify(state));}catch{storageEnabled=false;}
function commit(fn){const old=JSON.stringify(state);fn(state);try{if(storageEnabled)localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{state=JSON.parse(old);toast('Browser storage is full. Remove an uploaded asset and try again.');return false;}}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
const topic=id=>topics.find(t=>t.id===id);
const img=(src,alt='',cls='')=>`<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}" draggable="false">`;
const icon=n=>img(A+'interface/icon-'+n+'.svg','');
const button=(label,attrs='',kind='')=>`<button class="btn ${kind}" ${attrs}>${label}</button>`;
const link=(label,href,kind='')=>`<a class="btn ${kind}" href="${href}">${label}</a>`;
function questions(){const map=new Map(baseQuestions.map(q=>[q.id,q]));for(const q of state.customQuestions)map.set(q.id,q);return [...map.values()];}
function getQuestions(t,m){return questions().filter(q=>q.topic===t&&q.mode===(m==='daily'?'in-class':m));}
function activityKey(t,m){return m==='daily'?'daily:'+today():`${t}:${m}`;}
const assessed=m=>['in-class','after-class'].includes(m);
function labelMode(m){return {'in-class':'In-class activity','after-class':'After-class activity',daily:'Revision'}[m]||m;}
const earned=(t,m)=>state.submissions[`${t}:${m}`]?.review;
function completedTopics(){return topics.filter(t=>earned(t.id,'in-class')&&earned(t.id,'after-class')).length;}
function streak(){const days=new Set(state.activityDays);let date=new Date(today()+'T12:00:00Z');if(!days.has(today()))date.setUTCDate(date.getUTCDate()-1);let n=0;while(days.has(date.toISOString().slice(0,10))){n++;date.setUTCDate(date.getUTCDate()-1);}return n;}
function allPets(){return [{id:'crab',name:'Mira',common:'Fiddler Crab',latin:'',src:A+'characters/tubuca-arcuata.svg',head:[237,177]},{id:'spoonbill',name:'Pip',common:'Black-faced Spoonbill',latin:'',src:A+'characters/platalea-minor.svg',head:[202,74]},...state.assets.filter(a=>a.role==='character').map(a=>({id:a.id,name:a.name,common:'Custom companion',latin:'',src:a.data,head:null}))];}
function pet(){return allPets().find(p=>p.id===state.pet)||allPets()[0];}
function shopItems(){return [{id:'hat',name:'Exploration hat',description:'A little shade for your next adventure.',src:A+'accessories/exploration-hat.svg',price:60,sell:30,type:'accessory'},{id:'crown',name:'Explorer’s crown',description:'Celebrate discoveries with a golden touch.',src:A+'accessories/crown.svg',price:80,sell:40,type:'accessory'},{id:'food',name:'Companion food',description:'One portion restores 20 Hunger points.',src:A+'accessories/food.svg',price:15,sell:7,type:'item'},{id:'recovery',name:'Recovery item',description:'Restores 20 Health and 10 Stamina points.',src:A+'accessories/recovery-item.svg',price:25,sell:12,type:'item'},...state.assets.filter(a=>a.role==='accessory').map(a=>({id:a.id,name:a.name,description:'Custom accessory from the teacher workspace.',src:a.data,price:40,sell:20,type:'accessory'}))];}
function petArt(){const p=pet(),acc=shopItems().find(i=>i.id===state.equipped);let accessory='';if(acc&&p.head){const [x,y]=p.head;accessory=`<img class="accessory" alt="${esc(acc.name)}" src="${esc(acc.src)}" style="left:${(x-40)/5}%;top:${(y-52.8)/4.2}%;width:16%;height:19.0476%">`;}
return `<div class="companion-art">${img(p.src,p.common,'animal')}${accessory}</div>`;}
function scene(){const custom=state.assets.find(a=>a.id===state.scene);return `<div class="companion-scene">${custom?img(custom.data,custom.name,'scene-custom'):''}${petArt()}</div>`;}
function bars(){const s=state.stats[state.pet]||fresh().stats.crab;return `<div class="status-stack">${[['Health','health','#579a70'],['Hunger','hunger','#d6a64c'],['Stamina','stamina','#66a9b5']].map(([label,k,c])=>`<div class="status-row"><span>${label}</span><div class="track" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s[k]}"><div class="fill" style="width:${s[k]}%;background:${c}"></div></div><span class="muted">${s[k]}</span></div>`).join('')}</div>`;}
function namePanel(){const p=pet();return `<div class="pet-name"><h2>${esc(p.name)}</h2><p>${esc(p.common)}</p></div>`;}
function intro(eyebrow,title,description,extra=''){return `<div class="page-intro"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${description}</p></div>${extra}</div>`;}
function header(){return `<header class="topbar"><a class="brand" href="#home"><span class="brandmark">${icon('growth')}</span><span><strong>WETLAND EXPLORERS</strong><select class="course-select" id="course" aria-label="Course profile"><option value="biodiversity" ${state.course==='biodiversity'?'selected':''}>LIFS 2060 / Biodiversity</option><option value="plant" ${state.course==='plant'?'selected':''}>LIFS 2080 / Plant Biology — preview</option></select></span></a><div class="top-actions"><span class="pill">${role==='teacher'?'TEACHER DEMO':'STUDENT DEMO'}</span><button class="text-button" data-action="switch-role">${role==='teacher'?'Student view':'Teacher workspace'}</button><div class="balance">${img(A+'interface/coin.svg','Coins')}<strong>${state.coins}</strong><span>coins</span></div></div></header>`;}
function nav(view){return `<nav class="bottom-nav" aria-label="Student navigation">${[['home','Home'],['growth','Growth / Raising'],['shop','Shop'],['achievement','Achievement'],['settings','Settings']].map(([n,l])=>`<a class="nav-item ${view===n?'active':''}" ${view===n?'aria-current="page"':''} href="#${n}">${icon(n)}<span>${l}</span></a>`).join('')}</nav>`;}
function home(){const plant=state.course==='plant';return intro(plant?'Plant Biology · course profile preview':'LIFS 2060 · Biodiversity',plant?'A new course, a new learning trail.':'A little discovery, every day.',plant?'Explore a reusable course theme. Plant Biology activities are not configured in this demo.':'Explore your course. Care for your companion. Discover the wetland.')+`<div class="home-grid"><section class="card map-panel"><div class="card-head"><h2>${plant?'Your plant learning trail':'Your learning trail'}</h2><span class="eyebrow">${plant?'PROFILE PREVIEW':'4 MODULES'}</span></div><div class="map" aria-label="${plant?'Plant Biology profile map':'Illustrative wetland learning map'}">${plant?img(A+'plant-course-map.svg','Illustrative tree with learning stations','map-layer'):img(A+'map/wetland-park-background.svg','Wetland Park map with learning overlays','map-layer')}${(plant?[{name:'Roots',point:[260,465]},{name:'Stems',point:[355,320]},{name:'Leaves',point:[485,205]},{name:'Flowers',point:[268,115]}]:topics).map((t,i)=>{const done=!plant&&earned(t.id,'in-class')&&earned(t.id,'after-class');return `<button class="node ${done?'complete':!plant&&!unlocked(t.id)?'locked':'current'}" style="left:${t.point[0]/11.8}%;top:${t.point[1]/9.3}%" ${plant?'data-action="plant-preview"':`data-topic="${t.id}"`} aria-label="${t.name}: ${done?'finished':!plant&&!unlocked(t.id)?'in-class locked, after-class available':'in-class unlocked'}"><span class="node-disc"><span>${done?'✓':plant?i+1:unlocked(t.id)?'🔓':'🔒'}</span></span><span class="node-label">${t.name}</span></button>`;}).join('')}${!plant?`<button class="map-event" style="left:24%;top:51%" data-action="daily">Revision</button>`:''}</div><div class="legend"><span><i class="dot"></i>Finished</span><span><i class="dot amber"></i>In-class unlocked</span><span><i class="dot gray"></i>In-class locked</span><span class="map-note">Map: Hong Kong Wetland Park · learning markers added</span></div></section><section class="card companion-card"><div class="card-head"><h2>Your wetland companion</h2><button class="text-button" data-action="next-pet">Change</button></div>${scene()}${namePanel()}${bars()}<div class="actions pet-actions">${link('Care for '+esc(pet().name),'#growth')}${link('Change companion','#growth','secondary')}</div></section></div><div class="home-strip"><span><strong>Keep exploring</strong> · ${completedTopics()} of 4 topics reviewed · ${streak()}-day activity streak</span><div class="actions">${button(state.loginClaim===today()?'Daily bonus collected':'Claim daily bonus · +5 coins','data-action="login-bonus" '+(state.loginClaim===today()?'disabled':''),'secondary')}${!plant?button('Revision','data-action="daily"','ghost'):''}</div></div>${!plant?`<div class="section-title"><h2>Discover your next module</h2><span class="small muted">In class → after class → reflect</span></div><div class="topic-grid">${topics.map((t,i)=>`<article class="card topic-card" style="--accent:${t.color}"><p class="topic-number">MODULE 0${i+1}</p><h3>${t.name}</h3><p>${t.description}</p>${link('Explore module','#topic/'+t.id,'secondary')}</article>`).join('')}</div>`:`<div class="feedback"><strong>One platform, different course profiles.</strong><p>The tree illustrates how the same interface can support another course. Return to Biodiversity to try the configured activities.</p>${button('Return to Biodiversity','data-action="biodiversity"','secondary')}</div>`}`;}

function unlocked(id){return state.unlockedModules[id]===true;}
function unlockView(t){return intro('In-class activity · Locked',t.name,'Enter the code provided by your instructor to unlock this in-class activity.')+`<section class="card"><form id="unlock-form" data-module="${t.id}"><label for="unlock-code">Module access code</label><input id="unlock-code" name="code" maxlength="20" required autocomplete="off"><p id="unlock-error" class="error" role="alert"></p><div class="actions">${button('Unlock in-class activity','type="submit"')}${link('Open after-class activity','#activity/'+t.id+'/after-class','secondary')}</div></form></section>`;}
function codeControls(){return intro('Instructor controls','Module access codes','Set or generate a code for each in-class activity. After-class activities are always available.')+`<div class="feedback"><strong>Browser-local demonstration</strong><p>Codes and student unlocks are stored on this device. Changing a code does not revoke an existing unlock. Shared access across devices requires the production backend.</p></div><div class="topic-grid">${topics.map(t=>`<section class="card"><h2>${t.name}</h2><p>${unlocked(t.id)?'In-class unlocked for demo student':'In-class locked'} · After-class available</p><form data-code-form="${t.id}"><label for="code-${t.id}">In-class access code</label><input id="code-${t.id}" name="code" value="${esc(state.moduleCodes[t.id]||'')}" placeholder="Set a code" maxlength="20" required><p class="error" role="alert"></p><div class="actions">${button('Save code','type="submit"')}${button('Generate code','type="button" data-generate-code="'+t.id+'"','secondary')}</div></form></section>`).join('')}</div>`;}
function topicView(t){return `<a class="back" href="#home">← Back to the wetland</a>`+intro(t.eyebrow,t.name,t.description)+`<div class="activity-options">${['in-class','after-class'].map(m=>{const s=state.submissions[`${t.id}:${m}`],locked=m==='in-class'&&!unlocked(t.id);return `<section class="card activity-tile">${img(A+`interface/medal-${t.id}-${m}.svg`,'','tile-icon')}<p class="eyebrow">${locked?'LOCKED':s?.review?'REVIEWED':s?'AWAITING REVIEW':m==='in-class'?'UNLOCKED':'AVAILABLE'}</p><h2>${labelMode(m)}</h2><p>${m==='in-class'?'A focused concept check and a short explanation to connect ideas from the lesson.':'Apply the concept to a wetland situation and explain the reasoning behind your answer.'}</p>${link(locked?'Unlock with code':s?'View response':'Begin activity',`#activity/${t.id}/${m}`)}</section>`;}).join('')}</div><div class="habitat-banner" style="margin-top:24px"><h3>Look for the ecological connection</h3><p>Move beyond identifying a feature. Explain how it affects an organism, its habitat, or another part of the ecosystem.</p><div class="actions">${button('Open revision','data-action="daily"','secondary')}${link('View achievements','#achievement','secondary')}</div></div>`;}
function activityView(t,m){if(m==='in-class'&&!unlocked(t.id))return unlockView(t);const key=activityKey(t.id,m),sub=state.submissions[key],qs=sub?.questions||getQuestions(t.id,m),practice=!assessed(m);return `<a class="back" href="#topic/${t.id}">← ${t.name}</a>`+intro(labelMode(m),`${t.name}: connect the ideas`,practice?'Practice, reflect and earn coins. This activity does not award an assessed medal.':'Choose an answer, then explain your thinking. A teacher reviews the quality of your reasoning.')+`<div class="two-col"><section class="card">${(t.id==='ecosystem'&&m==='after-class')?`<div class="habitat-banner"><p class="eyebrow">A hypothetical wetland scenario</p><h3>A proposed aquaculture site</h3><p>A proposal would convert part of a wetland into an aquaculture site. Supporters anticipate food production and jobs; others raise concerns about nursery habitat and water quality. Consider alternatives and what evidence you would need.</p></div>`:''}${sub?`<div class="feedback ${sub.review?'':'review'}"><strong>${sub.review?'Teacher review complete':practice?'Practice complete':'Response submitted · awaiting teacher review'}</strong><p>${sub.review?esc(sub.review.feedback):practice?'Your answers and explanatory feedback are below. Keep connecting observations with ecological processes.':'Your explanation is saved. Completion and coins recognise participation; the assessed medal follows teacher review.'}</p>${sub.review?`<p>Reasoning score: <strong>${sub.review.score} / 10</strong></p>`:''}</div>`:''}<form id="activity-form" data-topic="${t.id}" data-mode="${m}">${qs.map((q,i)=>`<fieldset><legend><span class="eyebrow">QUESTION ${i+1} · ${q.type==='mc'?'MULTIPLE CHOICE':'SHORT EXPLANATION'}</span><br>${esc(q.prompt)}</legend>${q.type==='mc'?q.options.map((o,j)=>`<label class="option"><input type="radio" name="a-${q.id}" value="${j}" ${String(sub?.answers[q.id])===String(j)?'checked':''} ${sub?'disabled':'required'}><span>${esc(o)}</span></label>`).join(''):`<label class="small muted" for="answer-${q.id}">Your explanation · at least 20 characters</label><textarea id="answer-${q.id}" name="a-${q.id}" minlength="20" maxlength="4000" ${sub?'readonly':'required'} placeholder="Identify a process, explain its consequence, and use relevant evidence.">${esc(sub?.answers[q.id]||'')}</textarea>`}${sub?`<div class="feedback"><strong>${q.type==='mc'?(Number(sub.answers[q.id])===q.correct?'Correct ecological connection':'Consider the ecological connection'):'Reasoning prompt'}</strong><p>${esc(q.feedback)}</p>${q.type==='mc'?`<p class="small">Suggested answer: ${esc(q.options[q.correct])}</p>`:''}</div>`:''}</fieldset>`).join('')}${!qs.length?'<p class="muted">No questions are assigned yet. A teacher can add them in the question bank.</p>':''}<p class="error" id="activity-error" role="alert"></p>${!sub&&qs.length?button(practice?'Complete practice':'Submit for review','type="submit"'):link('Return to the wetland','#home','secondary')}</form></section><aside class="stack"><section class="card"><p class="eyebrow">Learning focus</p><h3>${t.eyebrow}</h3><p class="muted">${t.description}</p><ul class="evidence"><li>Identify a relevant ecological process.</li><li>Explain how or why the relationship works.</li><li>Support your explanation with an example or evidence.</li></ul></section><div class="reward">${img(A+'interface/coin.svg','')}<span><strong>${m==='daily'?10:15} coins</strong><br><span class="small">Once for completing this activity. Coins do not affect academic marks.</span></span></div>${assessed(m)?`<section class="card"><h3>Your achievement</h3><p class="muted">A submitted response is awaiting review. Your teacher approves a reasoning score before the assessed medal appears.</p>${link('View achievements','#achievement','secondary')}</section>`:''}<p class="small muted">Presentation question examples; subject to course-team review.</p></aside></div>`;}
function growth(){const p=pet(),s=state.stats[state.pet]||fresh().stats.crab;return intro('Your companion','A little care goes a long way.','Feed, help recover, and dress your wetland companion.')+`<div class="two-col"><section class="card companion-card care-hero">${scene()}${namePanel()}${bars()}<div class="actions pet-actions">${button('Feed · '+state.inventory.food+' available','data-care="feed" '+(!state.inventory.food||s.hunger>=100?'disabled':''))}${button('Recover · '+state.inventory.recovery+' available','data-care="recover" '+(!state.inventory.recovery||(s.health>=100&&s.stamina>=100)?'disabled':''),'secondary')}${button('Rest','data-care="rest" '+(state.restDays[state.pet]===today()||s.stamina>=100?'disabled':''),'secondary')}</div></section><div class="stack"><section class="card"><h2>Choose your companion</h2><div class="companion-choices">${allPets().map(p=>`<button class="companion-choice ${state.pet===p.id?'selected':''}" data-pet="${p.id}" aria-pressed="${state.pet===p.id}">${img(p.src,p.common)}<span>${esc(p.name)}</span></button>`).join('')}</div></section><section class="card"><h2>Make it your own</h2><p class="muted">Accessories change appearance only.</p><div class="actions">${button('No accessory','data-equip="none"','secondary')}${shopItems().filter(i=>i.type==='accessory'&&state.inventory[i.id]).map(i=>button((state.equipped===i.id?'✓ ':'')+esc(i.name),`data-equip="${i.id}"`,state.equipped===i.id?'':'secondary')).join('')}</div>${!p.head?'<p class="small muted" style="margin-top:12px">Accessory fitting is available for the two illustrated wetland species.</p>':''}<p class="small muted" style="margin-top:18px">Feeding restores Hunger. Recovery helps Health and Stamina. Rest is available once per day for each companion.</p>${link('Visit the shop','#shop','secondary')}</section></div></div>`;}
function shop(){return intro('The explorer’s shop','Little things for your next adventure.','Spend earned coins on care items and accessories. Sell items back when you no longer need them.')+`<div class="item-grid">${shopItems().map(i=>{const qty=state.inventory[i.id]||0;return `<article class="card item-card">${img(i.src,i.name,'item-art')}<h2>${esc(i.name)}</h2><p>${i.description}</p><div class="price">${i.price} coins <span class="muted small">· Owned: ${qty}</span></div><div class="actions">${button(i.type==='accessory'&&qty?'Owned':'Buy',`data-buy="${i.id}" ${state.coins<i.price||(i.type==='accessory'&&qty)?'disabled':''}`)}${button('Sell · '+i.sell,`data-sell="${i.id}" ${!qty?'disabled':''}`,'secondary')}${i.type==='accessory'&&qty?button(state.equipped===i.id?'Equipped':'Equip',`data-equip="${i.id}" ${state.equipped===i.id?'disabled':''}`,'ghost'):''}</div></article>`;}).join('')}</div><div class="feedback"><strong>Coins celebrate participation.</strong><p>Earn coins from the daily bonus, activities and revisions. Buying, selling and companion care do not affect course assessment.</p></div>`;}
function achievements(){const count=streak();return intro('Your learning journey','Every discovery leaves a mark.','Celebrate learning habits and see your reviewed course achievements.')+`<div class="section-title"><h2>Assessed achievements</h2><span class="small muted">Awarded after teacher review</span></div><div class="medal-grid">${topics.map(t=>`<section class="card medal-card"><h3>${t.name}</h3><div class="medal-pair">${['in-class','after-class'].map(m=>{const s=state.submissions[`${t.id}:${m}`];return `<div class="${s?.review?'earned':''}">${img(A+`interface/medal-${t.id}-${m}.svg`,t.name+' '+m+' medal')}<p>${m==='in-class'?'In class':'After class'}</p><span class="medal-status">${s?.review?'Reviewed · '+s.review.score+'/10':s?'Awaiting review':'Not started'}</span></div>`;}).join('')}</div></section>`).join('')}</div><div class="section-title"><h2>A habit worth celebrating</h2><span class="small muted">Participation recognition · no academic marks</span></div><div class="streak-grid">${[3,7,30].map(n=>`<div class="streak-card ${count>=n?'earned':''}">${img(A+'interface/badge-streak.svg','Streak badge')}<div><h3 style="margin-bottom:3px">${n}-day explorer</h3><p>${count>=n?'Achieved':`${Math.min(count,n)} of ${n} consecutive activity days`}</p></div></div>`).join('')}</div><div class="section-title"><h2>Recent activity</h2></div><section class="card">${Object.values(state.submissions).length?`<div class="table-wrap"><table><thead><tr><th>Activity</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${Object.values(state.submissions).filter(s=>s.mode!=='event').sort((a,b)=>b.at.localeCompare(a.at)).map(s=>`<tr><td>${topic(s.topic)?.name} · ${labelMode(s.mode)}</td><td>${esc(new Date(s.at).toLocaleDateString('en-GB'))}</td><td>${s.review?'Reviewed':assessed(s.mode)?'Awaiting review':'Practice complete'}</td><td>${link('View',`#activity/${s.topic}/${s.mode}`,'secondary')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your first discovery is waiting. Open a module on the map to get started.</div>'}</section>`;}
function settings(){return intro('Make yourself at home','Settings','Adjust your view and manage this presentation session.')+`<div class="two-col"><section class="card settings-list"><div><label for="display-setting">Display size</label><select id="display-setting"><option value="standard" ${state.settings.display==='standard'?'selected':''}>Standard · fit to screen</option><option value="large" ${state.settings.display==='large'?'selected':''}>Larger text</option></select><p class="small muted">The layout automatically adapts to your screen resolution.</p></div><label class="check"><input type="checkbox" id="motion-setting" ${state.settings.motion?'checked':''}>Gentle companion animation</label><div><h3>Session</h3><div class="actions">${button('Log out','data-action="logout"','secondary')}${button('Reset demo data','data-action="reset"','secondary')}</div></div></section><section class="card"><h2>About this demo</h2><p class="muted">This is a presentation workspace with one fictional student. The teacher and student views share this browser’s demo records.</p><p class="muted">HKUST Microsoft sign-in and gradebook connections are not active. No passwords or real student records are requested.</p><p class="small muted">${storageEnabled?'Progress and uploaded files are saved in this browser.':'Browser storage is unavailable; progress lasts for this open session.'}</p></section></div>`;}
function teacherTabs(active){return `<div class="teacher-banner"><span><strong>Teacher demo workspace</strong> · LIFS 2060 Biodiversity · One fictional student</span><button class="text-button" data-action="switch-role">Return to student view</button></div><nav class="tabs" aria-label="Teacher navigation">${[['overview','Overview'],['codes','Module codes'],['questions','Question bank'],['assets','Scenes & characters'],['reviews','Review responses']].map(([n,l])=>`<a href="#teacher/${n}" class="${n===active?'active':''}" ${n===active?'aria-current="page"':''}>${l}</a>`).join('')}</nav>`;}
function teacherView(tab='overview',id){if(!['overview','codes','questions','assets','reviews'].includes(tab))tab='overview';const subs=Object.values(state.submissions).filter(s=>assessed(s.mode)),pending=subs.filter(s=>!s.review);let body='';if(tab==='overview')body=intro('Course workspace','A thoughtful learning journey.','Prepare activities, personalise the wetland, and review student reasoning.')+`<div class="metric-grid"><section class="card metric"><strong>${questions().length}</strong><p>Questions in your bank</p></section><section class="card metric"><strong>${state.assets.length}</strong><p>Uploaded assets</p></section><section class="card metric"><strong>${pending.length}</strong><p>Responses awaiting review</p></section></div><div class="two-col"><section class="card"><h2>Prepare the next discovery</h2><p class="muted">Add multiple-choice questions with explanatory feedback, or ask students to explain a connection in their own words.</p>${link('Open question bank','#teacher/questions')}</section><section class="card"><h2>Review the reasoning</h2><p class="muted">Read the student’s explanation before approving a score and awarding the assessed medal.</p>${link('Review responses','#teacher/reviews','secondary')}</section></div><div class="feedback"><strong>A presentation-ready workflow.</strong><p>Content and uploaded artwork stay on this device. Institutional authentication, secure multi-user storage and grade transfer require a later backend implementation.</p></div>`;
if(tab==='questions'){const q=questions().find(q=>q.id===id);body=intro('Teaching resources','Question bank','Add or edit activities. Multiple-choice feedback and written explanations work together.',`<div class="actions">${button('Export bank','data-action="export-questions"','secondary')}</div>`)+`<div class="two-col"><section class="card"><h2>${q?'Edit question':'Create a question'}</h2><form id="question-form" data-id="${q?.id||''}"><div class="form-row"><div class="form-group"><label for="q-topic">Topic</label><select id="q-topic" name="topic">${topics.map(t=>`<option value="${t.id}" ${q?.topic===t.id?'selected':''}>${t.name}</option>`).join('')}</select></div><div class="form-group"><label for="q-mode">Activity</label><select id="q-mode" name="mode"><option value="in-class">In class</option><option value="after-class" ${q?.mode==='after-class'?'selected':''}>After class</option></select></div></div><div class="form-group"><label for="q-type">Question type</label><select id="q-type" name="type"><option value="mc">Multiple choice</option><option value="short" ${q?.type==='short'?'selected':''}>Short explanation</option></select></div><div class="form-group"><label for="q-prompt">Question prompt</label><textarea name="prompt" id="q-prompt" required minlength="10" maxlength="1500">${esc(q?.prompt||'')}</textarea></div><div id="mc-fields" ${q?.type==='short'?'hidden':''}><div class="form-group"><label for="q-options">Options · one per line, exactly four</label><textarea name="options" id="q-options" maxlength="2000">${esc(q?.options?.join('\n')||'')}</textarea></div><div class="form-group"><label for="q-correct">Correct option</label><select name="correct" id="q-correct">${[0,1,2,3].map(i=>`<option value="${i}" ${q?.correct===i?'selected':''}>Option ${i+1}</option>`).join('')}</select></div></div><div class="form-group"><label for="q-feedback">Explanatory feedback / reasoning guidance</label><textarea id="q-feedback" name="feedback" required minlength="10" maxlength="2000">${esc(q?.feedback||'')}</textarea></div><p class="error" id="question-error" role="alert"></p><div class="actions">${button(q?'Save changes':'Add question','type="submit"')}${q?link('Cancel','#teacher/questions','secondary'):''}</div></form></section><aside class="stack"><section class="card"><h2>Import a question bank</h2><p class="small muted">Upload the JSON format produced by Export bank. Question IDs update matching entries; new IDs add questions. Maximum 200 questions per import.</p><form id="import-form"><label for="question-import">Question JSON</label><input type="file" id="question-import" accept=".json,application/json" required><p class="error" id="import-error" role="alert"></p>${button('Import questions','type="submit" style="margin-top:12px"','secondary')}</form></section><section class="card"><h2>Current questions</h2><label for="bank-filter">Filter by topic</label><select id="bank-filter"><option value="all">All topics</option>${topics.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select><div id="question-list" style="margin-top:18px">${questions().map(q=>`<article class="question-row" data-q-topic="${q.topic}"><span class="pill">${topic(q.topic).name} · ${q.mode}</span><p style="margin-top:8px">${esc(q.prompt)}</p><div class="actions">${link('Edit','#teacher/questions/'+q.id,'secondary')}${state.customQuestions.some(c=>c.id===q.id)?button(baseQuestions.some(b=>b.id===q.id)?'Restore original':'Remove',`data-delete-question="${q.id}"`,'secondary'):''}</div></article>`).join('')}</div></section></aside></div>`;}
if(tab==='assets')body=intro('Your visual library','Bring the wetland to life.','Upload a scene, character or accessory and try it in the student workspace.')+`<div class="two-col"><section class="card"><h2>Add an asset</h2><form id="asset-form"><div class="form-group"><label for="asset-name">Asset name</label><input name="name" id="asset-name" required maxlength="60" placeholder="e.g. Mangrove morning"></div><div class="form-group"><label for="asset-role">Asset type</label><select name="role" id="asset-role"><option value="scene">Companion scene</option><option value="character">Character</option><option value="accessory">Accessory</option></select></div><div class="form-group"><label for="asset-file">SVG, PNG, JPEG or WebP · up to 500 KB</label><input id="asset-file" type="file" accept=".svg,.png,.jpg,.jpeg,.webp,image/svg+xml,image/png,image/jpeg,image/webp" required></div><p class="small muted">Character artwork works best on a transparent 500 × 420 canvas. Accessory artwork uses a 100 × 100 canvas. Uploaded characters do not yet support accessory fitting.</p><p class="error" id="asset-error" role="alert"></p>${button('Add to library','type="submit"')}</form></section><aside class="card"><h2>Try the result</h2><p class="muted">Use a scene as the companion backdrop, select a character, or add an accessory to the shop. The original wetland illustrations remain available.</p>${link('Preview student home','#home','secondary')}<p class="small muted" style="margin-top:20px">Uploads are local demonstration assets, not shared course resources.</p></aside></div><div class="section-title"><h2>Your uploaded assets</h2>${state.scene?button('Use original scene','data-action="clear-scene"','secondary'):''}</div><div class="asset-grid">${state.assets.length?state.assets.map(a=>`<article class="card">${img(a.data,a.name,'asset-preview')}<p class="eyebrow" style="margin-top:12px">${a.role}</p><h3>${esc(a.name)}</h3><div class="actions">${a.role!=='accessory'?button(a.role==='scene'?'Use scene':'Choose character',`data-use-asset="${a.id}"`):'<span class="small muted">Available in the shop</span>'}${button('Remove',`data-delete-asset="${a.id}"`,'secondary')}</div></article>`).join(''):'<section class="card empty">No uploaded assets yet.</section>'}</div>`;
if(tab==='reviews'){const sub=state.submissions[id];body=intro('Assessment workspace','Look closely at the reasoning.','Read the response, consider the ecological explanation, and approve a demo score.',button('Export reviewed results','data-action="export-results"','secondary'))+(sub&&assessed(sub.mode)?reviewForm(sub):`<section class="card"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Topic & activity</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${subs.map(s=>`<tr><td>Alex Lee<br><span class="small muted">DEMO-001</span></td><td>${topic(s.topic).name}<br>${labelMode(s.mode)}</td><td>${esc(new Date(s.at).toLocaleDateString('en-GB'))}</td><td>${s.review?'Reviewed · '+s.review.score+'/10':'Awaiting review'}</td><td>${link(s.review?'View review':'Review','#teacher/reviews/'+s.key,'secondary')}</td></tr>`).join('')}</tbody></table></div>${!subs.length?'<div class="empty">No submitted course activities yet. Complete an in-class or after-class activity in the student view to try this workflow.</div>':''}</section>`);}
if(tab==='codes')body=codeControls();return teacherTabs(tab)+body;}
function reviewForm(s){return `<a class="back" href="#teacher/reviews">← All responses</a><div class="two-col"><section class="card"><p class="eyebrow">Alex Lee · DEMO-001</p><h2>${topic(s.topic).name} · ${labelMode(s.mode)}</h2>${s.questions.map(q=>`<article style="margin-bottom:25px"><h3>${esc(q.prompt)}</h3><p style="white-space:pre-wrap">${esc(q.type==='mc'?q.options[Number(s.answers[q.id])]:s.answers[q.id])}</p>${q.type==='mc'?`<span class="pill ${Number(s.answers[q.id])===q.correct?'':'gold'}">${Number(s.answers[q.id])===q.correct?'Correct option':'Review concept'}</span>`:''}</article>`).join('')}</section><aside class="card"><h2>Review the explanation</h2><p class="small muted">Demo guidance: consider accuracy, causal explanation, relevant evidence, and acknowledgement of uncertainty. The course team will set the final rubric and award rules.</p><form id="review-form" data-key="${s.key}"><div class="form-group"><label for="review-score">Reasoning score · 0–10</label><input id="review-score" name="score" type="number" min="0" max="10" step="1" required value="${s.review?.score??''}"></div><div class="form-group"><label for="review-feedback">Feedback to the student</label><textarea id="review-feedback" name="feedback" required minlength="10" maxlength="3000" placeholder="Explain one strength and one next step.">${esc(s.review?.feedback||'')}</textarea></div><p class="small muted">Approval records the score and awards the corresponding reviewed-activity medal in this demo. No grade is sent to an institutional system.</p>${button(s.review?'Update review':'Approve review','type="submit"')}</form></aside></div>`;}
function welcome(){return `<section class="card welcome"><p class="eyebrow">Wetland Explorers</p><h1>A new discovery awaits.</h1>${img(A+'characters/tubuca-arcuata.svg','Fiddler Crab companion')}<p class="muted">Choose a demonstration workspace to continue.</p><div class="actions">${button('Enter as student','data-login="student"')}${button('Enter as teacher','data-login="teacher"','secondary')}</div><p class="small muted" style="margin-top:20px">Presentation accounts only. HKUST sign-in is not connected.</p></section>`;}
function render(){let [view,id,mode]=location.hash.replace(/^#/,'').split('/');view=view||'home';if(state.course==='plant'&&view!=='home'){commit(s=>s.course='biodiversity');}document.body.classList.toggle('large',state.settings.display==='large');document.body.classList.toggle('no-motion',!state.settings.motion);let content;
if(loggedOut)content=welcome();else if(view==='teacher'){role='teacher';content=teacherView(id,mode);}else{role='student';if(view==='topic')content=topic(id)?topicView(topic(id)):home();else if(view==='activity')content=topic(id)&&['in-class','after-class','daily'].includes(mode)?activityView(topic(id),mode):home();else content=({home,growth,shop,achievement:achievements,settings}[view]||home)();}
$('#app').innerHTML=`<div class="shell">${loggedOut?'':header()}<main id="main" tabindex="-1">${content}</main><footer class="demo-foot">Presentation demo · fictional student · ${storageEnabled?'saved in this browser':'session only'}</footer></div>${!loggedOut&&role==='student'?nav(['home','growth','shop','achievement','settings'].includes(view)?view:'home'):''}`;
bind();}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function daily(){const idx=Number(today().replace(/-/g,''))%topics.length;go('#activity/'+topics[idx].id+'/daily');}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(s){let v=String(s??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}
function perform(action){switch(action){
case 'switch-role':go(role==='teacher'?'#home':'#teacher/overview');break;
case 'daily':daily();break;

case 'plant-preview':toast('Plant Biology is a course-profile preview. Return to Biodiversity to try activities.');break;
case 'biodiversity':commit(s=>s.course='biodiversity');go('#home');render();break;
case 'login-bonus':if(state.loginClaim===today())return;if(commit(s=>{s.loginClaim=today();s.coins+=5;})){render();toast('Daily bonus collected · +5 coins');}break;
case 'next-pet':{const pets=allPets();choosePet(pets[(pets.findIndex(p=>p.id===state.pet)+1)%pets.length].id);break;}
case 'logout':loggedOut=true;role='student';render();break;
case 'reset':if(confirm('Reset this demo’s progress, coins, question edits and uploaded assets?')){state=fresh();try{if(storageEnabled)localStorage.setItem(KEY,JSON.stringify(state));}catch{}go('#home');render();toast('The presentation demo has been reset.');}break;
case 'clear-scene':if(commit(s=>s.scene=null)){render();toast('Original companion scene restored.');}break;
case 'export-questions':download('wetland-question-bank.json',JSON.stringify({version:1,questions:questions()},null,2),'application/json');toast('Question bank exported.');break;
case 'export-results':{const rows=[['Student','Topic','Activity','MC correct','MC total','Reasoning score /10','Review status','Teacher feedback']];for(const s of Object.values(state.submissions).filter(s=>assessed(s.mode)&&s.review)){const mc=s.questions.filter(q=>q.type==='mc');rows.push(['DEMO-001',topic(s.topic).name,s.mode,mc.filter(q=>Number(s.answers[q.id])===q.correct).length,mc.length,s.review.score,'Reviewed',s.review.feedback]);}download('wetland-demo-reviewed-results.csv',rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Reviewed demo results exported. No gradebook connection was used.');break;}
}}
function choosePet(id){if(!allPets().some(p=>p.id===id))return;if(commit(s=>{s.pet=id;s.stats[id]??={health:90,hunger:75,stamina:85};})){render();toast(pet().name+' is ready to explore.');}}
function validateQuestion(q){if(!q||typeof q!=='object'||!/^[-a-zA-Z0-9_]{1,80}$/.test(q.id)||!topic(q.topic)||!['in-class','after-class'].includes(q.mode)||!['mc','short'].includes(q.type))throw Error('Each question needs a valid id, topic, mode and type.');if(typeof q.prompt!=='string'||q.prompt.trim().length<10||q.prompt.length>1500||typeof q.feedback!=='string'||q.feedback.trim().length<10||q.feedback.length>2000)throw Error('Question and feedback must be complete, within their length limits.');if(q.type==='mc'&&(!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>typeof o!=='string'||!o.trim()||o.length>500)||!Number.isInteger(q.correct)||q.correct<0||q.correct>3))throw Error('Multiple-choice questions need four non-empty options and a correct index from 0 to 3.');return {id:q.id,topic:q.topic,mode:q.mode,type:q.type,prompt:q.prompt.trim(),feedback:q.feedback.trim(),...(q.type==='mc'?{options:q.options.map(o=>o.trim()),correct:q.correct}:{})};}
function safeSvg(raw){const doc=new DOMParser().parseFromString(raw,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('This SVG could not be read.');for(const el of doc.querySelectorAll('*')){if(['script','foreignobject','iframe','image','use','a','animate','animatetransform','set'].includes(el.localName.toLowerCase()))throw Error('Upload a self-contained SVG with static vector shapes only.');for(const a of el.attributes){if(/^on/i.test(a.name)||/href$/i.test(a.name)||/javascript:|@import|url\(\s*[^#]/i.test(a.value))throw Error('SVGs must not contain scripts or external references.');}}if(/@import|https?:\/\/(?!www\.w3\.org)|javascript:/i.test(raw.replace(/xmlns(?:\:[\w-]+)?=["'][^"']*["']/g,'')))throw Error('External SVG content is not supported.');}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('The selected file could not be read.'));r.readAsDataURL(file);});}
function bind(){
$$('[data-code-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const id=form.dataset.codeForm;const value=String(new FormData(form).get('code')||'').trim().toUpperCase();if(!/^[A-Z0-9-]{4,20}$/.test(value)){form.querySelector('[role=alert]').textContent='Use 4–20 letters, numbers or hyphens.';return;}if(commit(s=>{s.moduleCodes[id]=value;})){render();toast('Module code saved.');}});
$$('[data-generate-code]').forEach(b=>b.onclick=()=>{const bytes=crypto.getRandomValues(new Uint8Array(6));const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const code=[...bytes].map(v=>chars[v%chars.length]).join('');commit(s=>s.moduleCodes[b.dataset.generateCode]=code);render();toast('New module code generated.');});
if($('#unlock-form'))$('#unlock-form').onsubmit=e=>{e.preventDefault();const id=e.currentTarget.dataset.module;const code=String(new FormData(e.currentTarget).get('code')||'').trim().toUpperCase();if(!state.moduleCodes[id]||code!==state.moduleCodes[id]){$('#unlock-error').textContent=state.moduleCodes[id]?'Incorrect code. Please check with your instructor.':'Your instructor has not set a code yet.';return;}if(commit(s=>s.unlockedModules[id]=true)){render();toast('In-class activity unlocked.');}};

$$('[data-action]').forEach(b=>b.addEventListener('click',()=>perform(b.dataset.action)));
$$('[data-topic]').filter(b=>b.tagName==='BUTTON').forEach(b=>b.onclick=()=>go('#topic/'+b.dataset.topic));
$$('[data-login]').forEach(b=>b.onclick=()=>{loggedOut=false;role=b.dataset.login;go(role==='teacher'?'#teacher/overview':'#home');render();});
if($('#course'))$('#course').onchange=e=>{if(commit(s=>s.course=e.target.value)){role='student';go('#home');render();}};
$$('[data-pet]').forEach(b=>b.onclick=()=>choosePet(b.dataset.pet));
$$('[data-equip]').forEach(b=>b.onclick=()=>{const id=b.dataset.equip;if(id!=='none'&&!state.inventory[id])return;if(commit(s=>s.equipped=id==='none'?null:id)){render();toast(id==='none'?'Accessory removed.':'Accessory equipped.');}});
$$('[data-buy]').forEach(b=>b.onclick=()=>{const i=shopItems().find(i=>i.id===b.dataset.buy);if(!i||state.coins<i.price||(i.type==='accessory'&&state.inventory[i.id]))return;if(commit(s=>{s.coins-=i.price;s.inventory[i.id]=(s.inventory[i.id]||0)+1;})){render();toast(i.name+' added to your inventory.');}});
$$('[data-sell]').forEach(b=>b.onclick=()=>{const i=shopItems().find(i=>i.id===b.dataset.sell);if(!i||!state.inventory[i.id])return;if(commit(s=>{s.inventory[i.id]--;s.coins+=i.sell;if(s.equipped===i.id)s.equipped=null;})){render();toast(i.name+' sold · +'+i.sell+' coins');}});
$$('[data-care]').forEach(b=>b.onclick=()=>{const action=b.dataset.care;const s=state.stats[state.pet];if(!s)return;if(action==='feed'&&(!state.inventory.food||s.hunger>=100))return;if(action==='recover'&&(!state.inventory.recovery||(s.health>=100&&s.stamina>=100)))return;if(action==='rest'&&(state.restDays[state.pet]===today()||s.stamina>=100))return;if(commit(st=>{const p=st.stats[st.pet];if(action==='feed'){st.inventory.food--;p.hunger=Math.min(100,p.hunger+20);}else if(action==='recover'){st.inventory.recovery--;p.health=Math.min(100,p.health+20);p.stamina=Math.min(100,p.stamina+10);}else{p.stamina=Math.min(100,p.stamina+15);st.restDays[st.pet]=today();}})){render();toast(action==='feed'?'A good meal · Hunger restored.':action==='recover'?'Feeling better · Health and Stamina restored.':'A little rest · Stamina restored.');}});
if($('#display-setting'))$('#display-setting').onchange=e=>{commit(s=>s.settings.display=e.target.value);render();};
if($('#motion-setting'))$('#motion-setting').onchange=e=>{commit(s=>s.settings.motion=e.target.checked);render();};
if($('#activity-form'))$('#activity-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,{topic:t,mode:m}=form.dataset,key=activityKey(t,m);if(m==='in-class'&&!unlocked(t))return;if(state.submissions[key])return;const qs=getQuestions(t,m);if(!qs.length)return;const fd=new FormData(form),answers={};for(const q of qs){const v=fd.get('a-'+q.id);if(q.type==='mc'&&(v===null||!q.options[Number(v)])){ $('#activity-error').textContent='Choose an answer for each multiple-choice question.';return;}if(q.type==='short'&&String(v||'').trim().length<20){$('#activity-error').textContent='Please explain your thinking in at least 20 characters.';return;}answers[q.id]=q.type==='mc'?Number(v):String(v).trim();}const amount=m==='daily'?10:15;if(commit(s=>{s.submissions[key]={key,topic:t,mode:m,at:new Date().toISOString(),questions:JSON.parse(JSON.stringify(qs)),answers,review:null};if(!s.rewards.includes(key)){s.rewards.push(key);s.coins+=amount;}if(!s.activityDays.includes(today()))s.activityDays.push(today());})){render();window.scrollTo({top:0,behavior:'instant'});toast('Activity saved · +'+amount+' coins'+(assessed(m)?' · awaiting teacher review':''));}};
if($('#q-type'))$('#q-type').onchange=e=>$('#mc-fields').hidden=e.target.value==='short';
if($('#question-form'))$('#question-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form);try{const q=validateQuestion({id:form.dataset.id||'custom-'+Date.now(),topic:fd.get('topic'),mode:fd.get('mode'),type:fd.get('type'),prompt:fd.get('prompt'),feedback:fd.get('feedback'),options:String(fd.get('options')).split('\n').map(s=>s.trim()).filter(Boolean),correct:Number(fd.get('correct'))});if(commit(s=>{s.customQuestions=s.customQuestions.filter(c=>c.id!==q.id);s.customQuestions.push(q);})){go('#teacher/questions');render();toast('Question saved. Existing submitted responses retain their original questions.');}}catch(err){$('#question-error').textContent=err.message;}};
if($('#bank-filter'))$('#bank-filter').onchange=e=>$$('[data-q-topic]').forEach(row=>row.hidden=e.target.value!=='all'&&row.dataset.qTopic!==e.target.value);
$$('[data-delete-question]').forEach(b=>b.onclick=()=>{if(commit(s=>s.customQuestions=s.customQuestions.filter(q=>q.id!==b.dataset.deleteQuestion))){render();toast('Question bank updated.');}});
if($('#import-form'))$('#import-form').onsubmit=async e=>{e.preventDefault();const file=$('#question-import').files[0];try{if(!file||file.size>500000)throw Error('Choose a JSON file smaller than 500 KB.');const parsed=JSON.parse(await file.text()),list=Array.isArray(parsed)?parsed:parsed.questions;if(!Array.isArray(list)||!list.length||list.length>200)throw Error('Import a bank containing 1–200 questions.');const qs=list.map(validateQuestion);if(new Set(qs.map(q=>q.id)).size!==qs.length)throw Error('Question IDs must be unique within the import.');if(commit(s=>{const map=new Map(s.customQuestions.map(q=>[q.id,q]));qs.forEach(q=>map.set(q.id,q));s.customQuestions=[...map.values()];})){render();toast(qs.length+' questions imported.');}}catch(err){$('#import-error').textContent=err.message;}};
if($('#asset-form'))$('#asset-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),file=$('#asset-file').files[0],submit=form.querySelector('button[type=submit]');submit.disabled=true;try{if(!file||file.size>500000)throw Error('Select an asset smaller than 500 KB.');if(!/\.(svg|png|jpe?g|webp)$/i.test(file.name))throw Error('Use SVG, PNG, JPEG or WebP artwork.');if(/\.svg$/i.test(file.name))safeSvg(await file.text());const data=await fileData(file);await new Promise((resolve,reject)=>{const image=new Image();image.onload=resolve;image.onerror=()=>reject(Error('The selected file is not a readable image.'));image.src=data;});const asset={id:'asset-'+Date.now(),name:String(fd.get('name')).trim(),role:fd.get('role'),data};if(!asset.name)throw Error('Give the asset a name.');if(!['scene','character','accessory'].includes(asset.role))throw Error('Choose a supported asset type.');if(JSON.stringify(state.assets).length+data.length>2200000)throw Error('The demo asset library is full. Remove an asset before uploading another.');if(commit(s=>s.assets.push(asset))){render();toast('Asset added to your local library.');}}catch(err){if($('#asset-error'))$('#asset-error').textContent=err.message;submit.disabled=false;}};
$$('[data-use-asset]').forEach(b=>b.onclick=()=>{const a=state.assets.find(a=>a.id===b.dataset.useAsset);if(!a)return;if(a.role==='character')choosePet(a.id);else if(commit(s=>s.scene=a.id)){render();toast('Scene applied to the student companion panel.');}});
$$('[data-delete-asset]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteAsset;if(commit(s=>{s.assets=s.assets.filter(a=>a.id!==id);if(s.scene===id)s.scene=null;if(s.pet===id)s.pet='crab';if(s.equipped===id)s.equipped=null;delete s.inventory[id];delete s.stats[id];})){render();toast('Asset removed from this browser.');}});
if($('#review-form'))$('#review-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),score=Number(fd.get('score')),feedback=String(fd.get('feedback')).trim();if(!Number.isInteger(score)||score<0||score>10||feedback.length<10)return;if(commit(s=>s.submissions[form.dataset.key].review={score,feedback,at:new Date().toISOString()})){go('#teacher/reviews');toast('Review approved. The corresponding medal is now visible to the student.');}};
}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main')?.focus();return;}render();window.scrollTo({top:0,behavior:'instant'});});
render();
})();
